package org.sigf;
import org.sigf.app.*; import org.sigf.config.*; import org.sigf.security.*; import org.sigf.services.*; import org.sigf.ui.*; import org.sigf.domain.*;

import javafx.application.Platform;import javafx.scene.control.*;import javafx.stage.Stage;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import static org.junit.jupiter.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="SIGF_STARTUP_GUI_TEST",matches="true")
class StartupFlowTest {
 @Test void connectionFormOpensLoginWithDisposableDatabase()throws Exception {CountDownLatch initial=new CountDownLatch(1);AtomicReference<Stage> ref=new AtomicReference<>();AtomicReference<Throwable> error=new AtomicReference<>();Platform.startup(()->{try{Stage stage=new Stage();new Main().start(stage);ref.set(stage);assertNotNull(stage.getScene().lookup("#connectButton"));((TextField)stage.getScene().lookup("#dbPort")).setText("55439");((TextField)stage.getScene().lookup("#dbUser")).setText("sigftest");((PasswordField)stage.getScene().lookup("#dbPassword")).setText("test-only");((Button)stage.getScene().lookup("#connectButton")).fire();}catch(Throwable e){error.set(e);}finally{initial.countDown();}});assertTrue(initial.await(15,TimeUnit.SECONDS));if(error.get()!=null)throw new AssertionError(error.get());boolean found=false;for(int i=0;i<120&&!found;i++){Thread.sleep(100);CountDownLatch check=new CountDownLatch(1);AtomicBoolean ready=new AtomicBoolean();Platform.runLater(()->{ready.set(ref.get().getScene().lookup("#login") != null);check.countDown();});assertTrue(check.await(5,TimeUnit.SECONDS));found=ready.get();}assertTrue(found,"La pantalla de acceso no apareció");CountDownLatch closed=new CountDownLatch(1);Platform.runLater(()->{ref.get().close();closed.countDown();});assertTrue(closed.await(5,TimeUnit.SECONDS));Platform.exit();}
}
